  "source": """"TinyGPT fp32 con atención causal explícita; no depende de kernels Flash/SDPA."""
from dataclasses import dataclass
import math

import torch
from torch import nn
from torch.nn import functional as F


@dataclass(frozen=True)
class ModelConfig:
    dim: int = 64
    layers: int = 2
    heads: int = 2
    context: int = 64
    dropout: float = 0.0

    def __post_init__(self):
        if any(type(n) is not int or n <= 0 for n in (self.dim, self.layers, self.heads, self.context)):
            raise ValueError("Dimensiones deben ser enteros positivos")
        if self.dim % self.heads or not 0 <= self.dropout < 1:
            raise ValueError("Configuración de heads/dropout inválida")


class CausalAttention(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        self.heads = cfg.heads
        self.qkv = nn.Linear(cfg.dim, 3 * cfg.dim)
        self.proj = nn.Linear(cfg.dim, cfg.dim)
        self.dropout = nn.Dropout(cfg.dropout)
        self.register_buffer("causal", torch.ones(cfg.context, cfg.context, dtype=torch.bool).tril())

    def forward(self, x):
        b, t, d = x.shape
        q, k, v = self.qkv(x).chunk(3, dim=-1)
        q, k, v = [a.reshape(b, t, self.heads, d // self.heads).transpose(1, 2) for a in (q, k, v)]
        score = (q @ k.transpose(-2, -1)) / math.sqrt(d // self.heads)
        score = score.masked_fill(~self.causal[:t, :t], float("-inf"))
        weights = self.dropout(F.softmax(score, dim=-1))
        out = (weights @ v).transpose(1, 2).contiguous().reshape(b, t, d)
        return self.dropout(self.proj(out))


class Block(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        self.norm1 = nn.LayerNorm(cfg.dim)
        self.attention = CausalAttention(cfg)
        self.norm2 = nn.LayerNorm(cfg.dim)
        self.mlp = nn.Sequential(nn.Linear(cfg.dim, 4 * cfg.dim), nn.GELU(),
                                 nn.Linear(4 * cfg.dim, cfg.dim), nn.Dropout(cfg.dropout))

    def forward(self, x):
        x = x + self.attention(self.norm1(x))
        return x + self.mlp(self.norm2(x))


class TinyGPT(nn.Module):
    def __init__(self, cfg=ModelConfig()):
        super().__init__()
        self.cfg = cfg
        self.token = nn.Embedding(256, cfg.dim)
        self.position = nn.Embedding(cfg.context, cfg.dim)
        self.blocks = nn.ModuleList(Block(cfg) for _ in range(cfg.layers))
        self.norm = nn.LayerNorm(cfg.dim)
        self.head = nn.Linear(cfg.dim, 256, bias=False)
        self.apply(self._init)
        self.head.weight = self.token.weight

    @staticmethod
    def _init(module):
        if isinstance(module, (nn.Linear, nn.Embedding)):
            nn.init.normal_(module.weight, mean=0.0, std=0.02)
            if isinstance(module, nn.Linear) and module.bias is not None:
                nn.init.zeros_(module.bias)

    def forward(self, tokens, targets=None):
        if tokens.ndim != 2 or not 0 < tokens.shape[1] <= self.cfg.context:
            raise ValueError("tokens debe tener forma B x T con 0 < T <= context")
        if tokens.dtype not in (torch.int32, torch.int64):
            raise ValueError("tokens debe contener índices enteros")
        if targets is not None and targets.shape != tokens.shape:
            raise ValueError("targets de entrenamiento debe tener la misma forma que tokens")
        positions = torch.arange(tokens.shape[1], device=tokens.device)
        x = self.token(tokens) + self.position(positions)[None, :, :]
        for block in self.blocks:
            x = block(x)
        logits = self.head(self.norm(x))
        loss = None if targets is None else F.cross_entropy(logits.reshape(-1, 256), targets.reshape(-1))
        return logits, loss

import hashlib
import numpy as np
from dataclasses import asdict

@dataclass(frozen=True)
class TrainConfig:
    batch: int = 32
    lr: float = 0.003
    weight_decay: float = 0.01
    clip_norm: float = 1.0

class Trainer:
    def __init__(self, training_records, seed, model_cfg=ModelConfig(), train_cfg=TrainConfig(), device="cuda:0"):
        if (training_records.dtype != np.uint8 or training_records.ndim != 2
                or training_records.shape[1] != model_cfg.context + 1 or len(training_records) == 0):
            raise ValueError("Se requieren registros train uint8 de tamaño context+1")
        self.device = torch.device(device)
        self.cfg = train_cfg
        self.model = TinyGPT(model_cfg).to(self.device)
        self.data = torch.tensor(training_records.astype(np.int64), device=self.device)
        self.rng = torch.Generator(device="cpu").manual_seed(seed)
        self.optimizer = torch.optim.AdamW(self.model.parameters(), lr=train_cfg.lr,
                                           weight_decay=train_cfg.weight_decay, foreach=False, fused=False)
        self.steps = 0
        self.losses = []

    def step(self):
        self.model.train()
        idx = torch.randint(len(self.data), (self.cfg.batch,), generator=self.rng).to(self.device)
        rows = self.data[idx]
        _, loss = self.model(rows[:, :-1], rows[:, 1:])
        if not torch.isfinite(loss).item():
            raise RuntimeError("Loss no finita")
        self.optimizer.zero_grad(set_to_none=True)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(self.model.parameters(), self.cfg.clip_norm,
                                       error_if_nonfinite=True, foreach=False)
        self.optimizer.step()
        value = loss.item()
        self.steps += 1
        self.losses.append(value)
        return value

    @torch.inference_mode()
    def predict_last(self, contexts):
        if contexts.ndim != 2 or contexts.shape[1] != self.model.cfg.context or contexts.dtype != np.uint8:
            raise ValueError("Solo se aceptan contextos uint8 B x context")
        mode = self.model.training
        self.model.eval()
        predictions = []
        try:
            for start in range(0, len(contexts), self.cfg.batch):
                x = torch.tensor(contexts[start:start + self.cfg.batch].astype(np.int64), device=self.device)
                logits, _ = self.model(x)
                predictions.append(logits[:, -1, :].cpu().numpy())
            return np.concatenate(predictions)
        finally:
            self.model.train(mode)

    def gradient_digest(self):
        digest = hashlib.sha256()
        for name, parameter in sorted(self.model.named_parameters()):
            if parameter.grad is not None:
                digest.update(name.encode())
                digest.update(parameter.grad.detach().cpu().contiguous().numpy().tobytes())
        return digest.hexdigest()

    def configuration(self):
        return {"model": asdict(self.model.cfg), "training": asdict(self.cfg)}

class Candidate(Trainer):
    def train(self, steps):
        for _ in range(steps):
            self.step()

    def predict(self, contexts):
        return self.predict_last(contexts)
